/* Anatomy of a CSS ruleset */
/* Selector */
.button-primary {
  /* Property: Value; -> Declaration */
  background-color: #2563eb;
  color: #ffffff;
  padding: 0.75rem 1.5rem;
  border-radius: 6px;
}

/* Critical Rendering Path:
   HTML -> DOM Tree  \
                      --> Render Tree -> Layout (Reflow) -> Paint -> Composite
   CSS  -> CSSOM Tree /
*/

/* Selector evaluated right-to-left: matches all .link items first, then checks parents */
nav.main-menu ul li a.link {
  color: #3b82f6;
}

/* Modern CSS Reset snippet */
*, *::before, *::after {
  box-sizing: border-box;
}

body, h1, h2, h3, p, figure {
  margin: 0;
}

img, picture {
  max-width: 100%;
  display: block;
}

/* Matches EVERY paragraph inside .card, regardless of nesting depth */
.card p {
  color: #64748b;
}

/* Matches ONLY paragraphs that are direct children of .card */
.card > p {
  font-size: 1.125rem;
}

/* Adjacent: Only the first p immediately after h2 gets a top margin */
h2 + p {
  margin-top: 1rem;
}

/* General: All p elements that follow an h2 under the same parent */
h2 ~ p {
  line-height: 1.6;
}

/* 1. Starts with "https" */
a[href^="https://"] {
  color: #2563eb;
}

/* 2. Ends with ".pdf" */
a[href$=".pdf"]::after {
  content: " (PDF)";
}

/* 3. Contains "login" anywhere in class attribute */
button[class*="login"] {
  cursor: pointer;
}

/* Universal selector: targets all elements */
* {
  margin: 0;
}

/* Grouping selector: applies styles to h1, h2, and h3 */
h1, h2, h3 {
  font-family: 'Inter', sans-serif;
  color: #0f172a;
}

/* (0, 0, 0, 1) - Element */
p { color: black; }

/* (0, 0, 1, 0) - Class */
.lead { color: blue; }

/* (0, 1, 1, 1) - 1 ID, 1 Class, 1 Element */
#header .nav li { color: green; }

<!-- Inline style: (1, 0, 0, 0) beats all above -->
<p style="color: purple;">Inline wins</p>

