}

.text-red {
  color: red !important;
}

/* Parent has high specificity (0, 1, 0, 0) */
#main-content {
  color: blue;
}

/* Child has lowest direct specificity (0, 0, 0, 1) */
p {
  color: red; /* Direct selector wins over inherited style! */
}

