}

/* ASCII-art grid definition */
.layout {
  display: grid;
  grid-template-columns: 200px 1fr;
  grid-template-rows: auto 1fr auto;
  grid-template-areas:
    "header header"
    "sidebar content"
    "footer  ."; /* '.' is an empty cell */
}

.header  { grid-area: header; }
.sidebar { grid-area: sidebar; }
.content { grid-area: content; }
.footer  { grid-area: footer; }

/* Safe grid tracks that won't overflow with wide content */
.container {
  display: grid;
  grid-template-columns: 250px minmax(0, 1fr);
  gap: 20px;
}

/* If root font-size is 16px: */
html { font-size: 16px; }

/* 1.5rem = 16 * 1.5 = 24px everywhere */
h2 { font-size: 1.5rem; }

/* em compounds when nested: */
.parent { font-size: 1.5em; } /* 24px */
.parent .child { font-size: 1.5em; } /* 24 * 1.5 = 36px! (compounded) */

/* Fullscreen hero section */
.hero {
