/* HTML:
   <div>
     <h1>Heading</h1>
     <p>First paragraph</p>
   </div>
*/

/* Matches NOTHING! The 1st child is <h1>, not <p> */
p:first-child {
  color: red;
}

/* WINS: Matches the first <p> element */
p:first-of-type {
  color: green;
}

/* Specificity of :is() is (0, 1, 0, 0) because of #nav */
:is(header, #nav, footer) p {
  color: red;
}

/* Specificity of :where() is always ZERO (0, 0, 0, 1 for 'p' only) */
:where(header, #nav, footer) p {
  color: blue; /* Easily overridden by ANY class or element selector */
}

/* 1. Style a card parent ONLY if it contains an image */
.card:has(img) {
  grid-template-columns: 200px 1fr;
}

/* 2. Style a form label when its input is invalid */
label:has(+ input:invalid) {
  color: red;
}

/* 3. Style <body> when a modal dialog is open */
body:has(dialog[open]) {
  overflow: hidden; /* Lock scroll natively without JS! */
}

/* Accessible button focus */
button:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: 2px;
}

/* Highlight entire form row when input inside it has focus */
.form-group:focus-within {
  border-color: #2563eb;
  background-color: #f8fafc;
}

/* Custom tooltip using pseudo-elements */
.tooltip {
  position: relative;
}

.tooltip::after {
  content: attr(data-tooltip); /* Injects tooltip text from HTML attribute */
  position: absolute;
  bottom: 125%;
  left: 50%;
  transform: translateX(-50%);
  background: #0f172a;
  color: white;
  padding: 4px 8px;
  border-radius: 4px;
}

/* Pseudo-class (state) -> single colon */
a:hover { color: blue; }

/* Pseudo-element (virtual node) -> double colon */
p::first-line { font-weight: bold; }
input::placeholder { color: #94a3b8; }

/* ❌ Slow / Jank: triggers Layout reflow on every frame */
.card-slow {
  transition: top 0.3s ease, width 0.3s ease;
}
.card-slow:hover {
  top: -10px;
}

/* ✅ Fast / 60fps: GPU composite-only */
.card-fast {
  transition: transform 0.3s ease;
}
.card-fast:hover {
  transform: translateY(-10px);
}

/* Pure CSS accordion animation without fixed height! */
.accordion-content {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.3s ease-out;
}

.accordion-content.is-open {
  grid-template-rows: 1fr;
}

.accordion-inner {
  overflow: hidden; /* Crucial for 0fr collapsing */
}

/* Centering an absolutely positioned element perfectly */
.modal {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%); /* Shifts by 50% of its OWN dimensions */
}

/* Door swing rotation */
.door {
  transform-origin: left center; /* Swings from left hinge */
  transition: transform 0.5s;
}
.door.open {
  transform: rotateY(-90deg);
}

@keyframes slideInFade {
  0% {
    opacity: 0;
    transform: translateY(20px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

.toast {
  animation: slideInFade 0.4s ease forwards; /* Stays at 100% state after animation ends */
}

/* ✅ Mobile-first approach */
/* Base mobile styles: single column */
.container {
  display: flex;
  flex-direction: column;
}

/* Tablet & desktop: progressive enhancement */
@media (min-width: 768px) {
  .container {
    flex-direction: row;
  }
}

/* Respect user motion preferences */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

:root {
  --bg-color: #ffffff;
  --text-color: #0f172a;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg-color: #0f172a;
