  }
}

/* Specificity is (0, 0, 1, 1): 'p' (0,0,0,1) + '.lead' (0,0,1,0) */
p:not(.lead) {
  color: #334155;
}

/* Strip border from all list items except the last */
li:not(:last-child) {
  border-bottom: 1px solid #e2e8f0;
}

/* GPU-driven CSS animation (unaffected by JS thread lockup) */
@keyframes spin {
  to { transform: rotate(360deg); }
}
.spinner {
  animation: spin 1s linear infinite;
}

/* ❌ Old verbose syntax: */
@media (min-width: 768px) and (max-width: 1024px) {
  .tablet-layout { display: block; }
}

/* ✅ Modern Range Syntax: */
@media (768px <= width <= 1024px) {
  .tablet-layout { display: block; }
}

/* Single boundary: */
@media (width >= 1200px) {
  .desktop-layout { display: block; }
}

/* Dynamic runtime scoping */
:root {
  --brand-color: #2563eb;
}

.theme-dark {
  --brand-color: #60a5fa; /* Seamless component theming */
}

/* Modifying via JavaScript */
document.documentElement.style.setProperty('--brand-color', '#10b981');

/* Nested fallback: uses --accent, then --primary, then red */
.badge {
  background-color: var(--accent, var(--primary, #ef4444));
  padding: var(--padding, 0.5rem 1rem);
}

/* Fluid heading that scales smoothly across all devices */
h1 {
  font-size: clamp(2rem, 5vw + 1rem, 4.5rem);
  line-height: 1.1;
}

/* calc gotcha */
.sidebar {
  /* ❌ Invalid syntax: fails to parse! */
  /* width: calc(100%-50px); */

  /* ✅ Valid: space around minus sign */
  width: calc(100% - 50px);
}

/* min() provides responsive ceiling */
.modal {
  width: min(90vw, 600px); /* 90% of screen on mobile, capped at 600px on desktop */
}

/* Method 1: Grid (cleanest) */
.center-grid {
  display: grid;
  place-items: center;
}

/* Method 2: Flexbox */
.center-flex {
  display: flex;
  justify-content: center;
  align-items: center;
}

/* Method 3: Flex + margin: auto */
.parent { display: flex; }
.child  { margin: auto; }

/* Modern sole use case for float: Magazine text wrap */
.article-img {
  float: left;
  margin-right: 1.5rem;
  margin-bottom: 1rem;
}

/* Modern replacement for clearfix: */
.container {
  display: flow-root; /* Cleanly establishes a BFC containing floats */
}

/* Rebranding all form inputs with 1 line */
:root {
  accent-color: #2563eb;
}

/* Custom styled search input */
input[type="search"] {
  appearance: none;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
}

/* Fast rendering table with strict column boundaries */
table {
  table-layout: fixed;
  width: 100%;
  border-collapse: collapse;
}

td {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Perfect modern responsive card image */
.card-img {
  width: 100%;
  aspect-ratio: 16 / 9; /* Reserves space immediately: 0 CLS */
  object-fit: cover;    /* Prevents stretching or squishing */
  object-position: center;
  display: block;
}

/* Circle avatar */
.avatar {
  clip-path: circle(50% at 50% 50%);
}

/* Triangle shape */
.triangle {
  width: 100px;
  height: 100px;
  background: #2563eb;
  clip-path: polygon(50% 0%, 0% 100%, 100% 100%);
}

/* Create a 20% transparent tint natively */
.button-tint {
  background: color-mix(in srgb, #2563eb 80%, transparent);
}

/* Mixing brand color with black for hover state */
.button:hover {
  background: color-mix(in oklch, var(--brand) 85%, black);
}

/* Pure CSS Floating Label */
.input-group {
  position: relative;
}

.input-group input {
  padding: 1.25rem 0.75rem 0.5rem;
}

.input-group label {
  position: absolute;
  top: 1rem;
  left: 0.75rem;
  transition: all 0.2s ease;
  pointer-events: none;
}

/* Float label up when focused OR text is typed */
.input-group input:focus + label,
.input-group input:not(:placeholder-shown) + label {
  top: 0.25rem;
  font-size: 0.75rem;
  color: #2563eb;
}

/* ❌ Casts a square shadow around transparent PNG icon */
.icon-box {
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.3);
}

/* ✅ Casts shadow around the actual silhouette of the PNG/SVG */
.icon-filter {
  filter: drop-shadow(0 4px 10px rgba(0, 0, 0, 0.3));
}

/* Modern Glassmorphism Card */
.glass-card {
  background: rgba(255, 255, 255, 0.2);
  backdrop-filter: blur(16px) saturate(180%);
  -webkit-backdrop-filter: blur(16px) saturate(180%); /* Safari support */
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 12px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
}

/* 1. Linear: Angle direction */
.linear {
  background-image: linear-gradient(135deg, #2563eb, #9333ea);
}

/* 2. Conic: Pure CSS Pie Chart (70% blue, 30% gray) */
.pie-chart {
  border-radius: 50%;
  background-image: conic-gradient(#2563eb 0% 70%, #e2e8f0 70% 100%);
}

/* ❌ Old physical approach (requires duplicate RTL overrides) */
.icon {
  margin-right: 12px;
}
[dir="rtl"] .icon {
  margin-right: 0;
  margin-left: 12px; /* Tedious maintenance */
}

/* ✅ Modern logical property (adapts automatically to LTR and RTL!) */
.icon {
  margin-inline-end: 12px; /* Flips direction automatically */
}

/* Vertical sidebar tab label */
.vertical-tab {
  writing-mode: vertical-rl;
  text-orientation: mixed;
  padding: 1rem 0.5rem;
}

/* Industry standard Screen Reader Only utility */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* Compliant high-contrast palette */
:root {
  --bg: #ffffff;
  --text-normal: #1e293b; /* Ratio ~14:1 (Passes AAA) */
  --text-muted: #64748b;  /* Ratio ~4.6:1 (Passes AA) */
}

/* ❌ Causes Layout Reflow + Repaint + Composite on every frame */
.box {
  transition: width 0.3s;
}

/* ✅ Causes ONLY Compositing on GPU */
.box {
  transition: transform 0.3s;
}

/* 1. will-change: GPU promotion hint */
.animated-card {
