/* Native CSS Nesting */
.card {
  padding: 1.5rem;
  background: white;

  /* Direct child nesting */
  h2 {
    color: #1e293b;
  }

  /* Ampersand for pseudo-classes */
  &:hover {
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.1);
